package com.mg.fixturecockpitsim;
import android.content.Context;import android.graphics.*;import android.view.View;
/** AVM-8.9 continuous airport scene: interior hangar, aligned taxi/runway, forward-moving runway and wave sea. */
public final class RunwayHudView extends View{
 private final Paint f=new Paint(3),l=new Paint(3);private final Path p=new Path();private volatile float altitudeM,speedMps,route,groundProgress,headingDeg;private volatile boolean onGround,demoMode;private volatile String phase="";private float scroll;private long last;
 public RunwayHudView(Context c){super(c);setWillNotDraw(false);f.setStyle(Paint.Style.FILL);l.setStyle(Paint.Style.STROKE);l.setStrokeCap(Paint.Cap.ROUND);}
 public void setDemoMode(boolean e){demoMode=e;postInvalidateOnAnimation();}public void setDemoProgress(double s){route=(float)Math.max(0,s);postInvalidateOnAnimation();}public void setGroundProgress(double q,double hdg){groundProgress=(float)Math.max(0,Math.min(1,q));headingDeg=(float)hdg;postInvalidateOnAnimation();}public void setFlightState(double a,double s,boolean g,String ph){altitudeM=(float)Math.max(0,a);speedMps=(float)Math.max(0,s);onGround=g;phase=ph==null?"":ph;postInvalidateOnAnimation();}
 protected void onDraw(Canvas c){super.onDraw(c);long n=System.nanoTime();float dt=last==0?.016f:Math.min(.05f,(n-last)/1e9f);last=n;scroll=(scroll+speedMps*dt*.030f)%1;int w=getWidth(),h=getHeight();float hz=h*(.47f+.07f*Math.min(1,altitudeM/1200));sky(c,w,h,hz);if(phase.contains("HANGAR")){hangarInterior(c,w,h,hz);return;}airport(c,w,h,hz);if(phase.contains("TAXI")){taxiway(c,w,h,hz);if(speedMps>1)postInvalidateOnAnimation();return;}if(demoMode&&phase.contains("ORBIT")){scenery(c,w,h,hz);if(speedMps>1)postInvalidateOnAnimation();return;}boolean rw=onGround||phase.contains("RUNWAY")||phase.contains("TAKEOFF")||phase.contains("ROTATE")||phase.contains("APPROACH")||phase.contains("FLARE")||phase.contains("ROLLOUT")||phase.contains("COMPLETE");if(rw)runway(c,w,h,hz);if(speedMps>1)postInvalidateOnAnimation();}
 private void sky(Canvas c,int w,int h,float hz){f.setShader(new LinearGradient(0,0,0,hz,0xff0d2238,0xff3f6d8e,Shader.TileMode.CLAMP));c.drawRect(0,0,w,hz,f);f.setShader(null);}
 private void hangarInterior(Canvas c,int w,int h,float hz){float q=groundProgress,cx=w*.5f;f.setColor(0xff171b1e);c.drawRect(0,0,w,h,f);float doorTop=h*.22f,doorBot=h*.86f,doorHalf=w*(.18f+.12f*q);f.setColor(0xff7196ad);c.drawRect(cx-doorHalf,doorTop,cx+doorHalf,doorBot,f);f.setColor(0xff314b32);c.drawRect(cx-doorHalf,doorTop+h*.50f,cx+doorHalf,doorBot,f);l.setColor(0xffd8c640);l.setStrokeWidth(5);c.drawLine(cx,doorBot,cx,h,l);
  f.setColor(0xff2a3034);p.reset();p.moveTo(0,0);p.lineTo(cx-doorHalf,doorTop);p.lineTo(cx-doorHalf,doorBot);p.lineTo(0,h);p.close();c.drawPath(p,f);p.reset();p.moveTo(w,0);p.lineTo(cx+doorHalf,doorTop);p.lineTo(cx+doorHalf,doorBot);p.lineTo(w,h);p.close();c.drawPath(p,f);p.reset();p.moveTo(0,0);p.lineTo(w,0);p.lineTo(cx+doorHalf,doorTop);p.lineTo(cx-doorHalf,doorTop);p.close();f.setColor(0xff22282c);c.drawPath(p,f);
  l.setColor(0xff59636a);l.setStrokeWidth(3);for(int i=1;i<7;i++){float x=w*i/7f;c.drawLine(x,0,lerp(cx-doorHalf,cx+doorHalf,i/7f),doorTop,l);}for(int i=0;i<6;i++){float y=h*(.18f+i*.12f);c.drawLine(0,y,cx-doorHalf,lerp(doorTop,doorBot,i/5f),l);c.drawLine(w,y,cx+doorHalf,lerp(doorTop,doorBot,i/5f),l);}f.setColor(0xffffd76b);for(int i=0;i<8;i++){float x=w*(.12f+i*.11f);c.drawCircle(x,h*.12f,3,f);}f.setColor(0xe8ffffff);f.setTextSize(Math.max(20,w*.022f));c.drawText(q<.45f?"HANGAR 01 • MOTOR START":"HANGAR 01 • KAPI AÇIK • TAXI",w*.04f,h*.90f,f);}
 private void taxiway(Canvas c,int w,int h,float hz){float q=groundProgress;f.setColor(0xff2d422f);c.drawRect(0,hz,w,h,f);float cx=w*.5f;float farW=w*.055f,nearW=w*.24f;p.reset();p.moveTo(cx-farW,hz+h*.03f);p.lineTo(cx+farW,hz+h*.03f);p.lineTo(cx+nearW,h);p.lineTo(cx-nearW,h);p.close();f.setColor(0xff4d5255);c.drawPath(p,f);l.setColor(0xffe4c62e);l.setStrokeWidth(4);c.drawLine(cx,hz+h*.03f,cx,h,l);for(int i=0;i<15;i++){float z=i/14f,y=lerp(hz+h*.04f,h,z*z),half=lerp(farW,nearW,z);f.setColor(0xff3c8fff);c.drawCircle(cx-half,y,2+3*z,f);c.drawCircle(cx+half,y,2+3*z,f);}if(q>.70f){f.setColor(0x99ffffff);f.setTextSize(Math.max(18,w*.02f));c.drawText("RWY 27 • LINE UP",w*.68f,hz+h*.18f,f);}f.setColor(0xe8ffffff);f.setTextSize(Math.max(15,w*.017f));c.drawText("HDG "+String.format(java.util.Locale.US,"%03.0f",(headingDeg%360+360)%360),w*.04f,h*.90f,f);}
 private void runway(Canvas c,int w,int h,float hz){float near=1-Math.min(1,altitudeM/950),fh=w*(.022f+.01f*near),nh=w*(onGround?.45f:(.14f+.28f*near)),fy=hz+h*(.012f+.018f*near),ny=h*(onGround?.995f:(.70f+.28f*near)),cx=w*.5f;f.setColor(0xff29402a);c.drawRect(0,hz,w,h,f);p.reset();p.moveTo(cx-fh*1.4f,fy);p.lineTo(cx+fh*1.4f,fy);p.lineTo(cx+nh*1.14f,ny);p.lineTo(cx-nh*1.14f,ny);p.close();f.setColor(0xff676a69);c.drawPath(p,f);p.reset();p.moveTo(cx-fh,fy);p.lineTo(cx+fh,fy);p.lineTo(cx+nh,ny);p.lineTo(cx-nh,ny);p.close();f.setColor(0xff303335);c.drawPath(p,f);
  l.setColor(0xfff3f2ed);l.setStrokeWidth(Math.max(2,w*.0024f));c.drawLine(cx-fh,fy,cx-nh,ny,l);c.drawLine(cx+fh,fy,cx+nh,ny,l);for(int i=0;i<22;i++){float q=(i/22f+scroll)%1f,z=q*q,y=lerp(fy,ny,z);l.setStrokeWidth(2+13*z);l.setColor(0xffffffff);c.drawLine(cx,y,cx,y+5+34*z,l);}for(int i=0;i<25;i++){float q=i/24f,z=q*q,y=lerp(fy,ny,z),half=lerp(fh,nh,z),r=1+4*z;f.setColor(0xfff5f1dc);c.drawCircle(cx-half,y,r,f);c.drawCircle(cx+half,y,r,f);}
  float numberProgress=phase.contains("TAKEOFF")?groundProgress:0f;float nz=Math.min(.98f,.76f+numberProgress*.34f),y=lerp(fy,ny,nz),half=lerp(fh,nh,nz);if(y<h*1.03f){f.setColor(0xffffffff);for(int i=-4;i<=4;i++)if(i!=0)c.drawRect(cx+i*half*.105f-half*.035f,y,cx+i*half*.105f+half*.035f,y+22+32*near,f);f.setTextAlign(Paint.Align.CENTER);f.setTextSize(Math.max(28,w*.04f));c.drawText("27",cx,y+72,f);f.setTextAlign(Paint.Align.LEFT);}float py=lerp(fy,ny,.58f),ph=lerp(fh,nh,.58f);for(int i=0;i<4;i++){f.setColor(i<2?0xffff3b30:0xffffffff);c.drawCircle(cx-ph*1.2f+i*10,py,4,f);}}
 private void airport(Canvas c,int w,int h,float hz){f.setColor(0xff344236);c.drawRect(0,hz,w,hz+h*.12f,f);f.setColor(0xff4b5151);for(int i=0;i<7;i++){float x=w*(.025f+i*.055f),bh=h*(.018f+(i%3)*.008f);c.drawRect(x,hz-bh,x+w*.04f,hz,f);}float x=w*.80f;f.setColor(0xff4b5154);c.drawRect(x-5,hz-h*.075f,x+5,hz,f);c.drawRect(x-16,hz-h*.086f,x+16,hz-h*.068f,f);}
 private void scenery(Canvas c,int w,int h,float hz){float t=Math.min(300,route);String label;if(t<45){label="SAHİL ÜZERİ TIRMANIŞ";coast(c,w,h,hz,.25f);}else if(t<90){label="DAĞLARA YAKLAŞMA";mountains(c,w,h,hz,.45f,false);}else if(t<145){label="VADİ İÇİ UÇUŞ";mountains(c,w,h,hz,.72f,true);}else if(t<205){label="DAĞ YOLU TAKİBİ";mountains(c,w,h,hz,.92f,true);road(c,w,h,hz);}else if(t<250){label="GÖL / KIYI GEÇİŞİ";lake(c,w,h,hz);}else if(t<280){label="YÜKSEK ARAZİ / DÖNÜŞ";mountains(c,w,h,hz,.68f,false);}else{label="HAVALİMANINA DÖNÜŞ";mountains(c,w,h,hz,.35f,false);airport(c,w,h,hz);}f.setColor(0xe8ffffff);f.setTextSize(Math.max(20,w*.022f));c.drawText(label,w*.04f,h*.88f,f);}
 private void mountains(Canvas c,int w,int h,float hz,float scale,boolean valley){p.reset();p.moveTo(0,h);for(int i=0;i<=14;i++){float x=w*i/14f,y=hz-h*scale*(.04f+.12f*(float)Math.abs(Math.sin(i*1.31+route*.010)));if(valley&&i>5&&i<9)y+=h*.13f;p.lineTo(x,y);}p.lineTo(w,h);p.close();f.setColor(0xff435748);c.drawPath(p,f);}
 private void coast(Canvas c,int w,int h,float hz,float q){mountains(c,w,h,hz,q,false);water(c,w,h,hz+h*.08f);}
 private void lake(Canvas c,int w,int h,float hz){mountains(c,w,h,hz,.55f,true);water(c,w,h,hz+h*.13f);}
 private void water(Canvas c,int w,int h,float top){f.setShader(new LinearGradient(0,top,0,h,0xff2e667f,0xff0f3148,Shader.TileMode.CLAMP));c.drawRect(0,top,w,h,f);f.setShader(null);for(int row=0;row<18;row++){float y=top+(h-top)*(row+.5f)/18f;float amp=2+row*.35f,span=22+row*3;Path wp=new Path();wp.moveTo(0,y);for(int x=0;x<=w;x+=12){float yy=y+(float)Math.sin(x/span+route*.12f+row*.63f)*amp;wp.lineTo(x,yy);}l.setColor(row%3==0?0x66d7edf5:0x2f9bc5d7);l.setStrokeWidth(1+row*.04f);c.drawPath(wp,l);}for(int i=0;i<26;i++){float x=(i*97+route*9)%Math.max(1,w),y=top+(h-top)*(.18f+((i*37)%70)/100f);f.setColor(0x55ffffff);c.drawOval(x,y,x+10+i%18,y+2,f);}}
 private void road(Canvas c,int w,int h,float hz){l.setColor(0xff767a78);l.setStrokeWidth(Math.max(10,w*.018f));p.reset();p.moveTo(w*.15f,h);p.cubicTo(w*.40f,h*.70f,w*.36f,h*.58f,w*.58f,hz+h*.08f);c.drawPath(p,l);l.setColor(0xffe2c94a);l.setStrokeWidth(2);c.drawPath(p,l);}
 private static float lerp(float a,float b,float t){return a+(b-a)*t;}
}
